import React, { useEffect, useRef } from "react";
import * as THREE from "three";

export const Hero3D: React.FC = () => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- Scene Setup ---
    const width = mountRef.current.clientWidth;
    const height = mountRef.current.clientHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 100);
    camera.position.set(0, 0, 18);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.0;
    mountRef.current.appendChild(renderer.domElement);

    // --- Lighting ---
    // Soft ambient for cartoon look
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);

    const mainLight = new THREE.DirectionalLight(0xffffff, 1.8);
    mainLight.position.set(10, 10, 15);
    mainLight.castShadow = true;
    mainLight.shadow.mapSize.width = 2048;
    mainLight.shadow.mapSize.height = 2048;
    scene.add(mainLight);

    // Rim light
    const rimLight = new THREE.SpotLight(0xbad7ff, 5);
    rimLight.position.set(-10, 5, 5);
    rimLight.lookAt(0, 0, 0);
    scene.add(rimLight);

    // Engine glow
    const engineLight = new THREE.PointLight(0xf43f5e, 2, 20);
    engineLight.position.set(5, -5, 5);
    scene.add(engineLight);

    // --- Rocket Construction (High-Tech / Sci-Fi / Masculine) ---
    const rocketGroup = new THREE.Group();
    scene.add(rocketGroup);

    // Materials - Sleek, Metallic, High-Tech
    const matBodyMain = new THREE.MeshToonMaterial({ color: 0xe2e8f0 }); // Silver/White
    const matBodyDark = new THREE.MeshToonMaterial({ color: 0x1e293b }); // Dark Slate
    const matAccent = new THREE.MeshToonMaterial({ color: 0x6366f1 }); // Indigo Accent
    const matGlow = new THREE.MeshBasicMaterial({ color: 0x0ea5e9 }); // Cyan Glow
    const matEngine = new THREE.MeshStandardMaterial({
      color: 0x334155,
      metalness: 0.8,
      roughness: 0.2,
    });

    // 1. Nose Cone (Sharp, Aerodynamic)
    const noseGeo = new THREE.ConeGeometry(0.5, 1.5, 32);
    const nose = new THREE.Mesh(noseGeo, matAccent);
    nose.position.y = 2.0;
    nose.castShadow = true;
    rocketGroup.add(nose);

    // 2. Main Fuselage (Cylinder)
    const bodyGeo = new THREE.CylinderGeometry(0.5, 0.6, 2.5, 32);
    const body = new THREE.Mesh(bodyGeo, matBodyMain);
    body.position.y = 0.0;
    body.castShadow = true;
    rocketGroup.add(body);

    // 3. Cockpit / Sensor Array (Angular, embedded)
    const cockpitGeo = new THREE.BoxGeometry(0.6, 0.8, 0.5);
    const cockpit = new THREE.Mesh(cockpitGeo, matBodyDark);
    cockpit.position.set(0, 0.5, 0.3);

    // Glowing Visor
    const visorGeo = new THREE.BoxGeometry(0.5, 0.3, 0.6);
    const visor = new THREE.Mesh(visorGeo, matGlow);
    visor.position.set(0, 0.6, 0.35);

    rocketGroup.add(cockpit);
    rocketGroup.add(visor);

    // 4. Side Intakes / details
    const intakeGeo = new THREE.CapsuleGeometry(0.2, 1.0, 4, 8);
    const leftIntake = new THREE.Mesh(intakeGeo, matBodyDark);
    leftIntake.position.set(-0.55, 0, 0);
    rocketGroup.add(leftIntake);

    const rightIntake = new THREE.Mesh(intakeGeo, matBodyDark);
    rightIntake.position.set(0.55, 0, 0);
    rocketGroup.add(rightIntake);

    // 5. Wings/Fins (Delta geometry, sharp angles)
    const finShape = new THREE.Shape();
    finShape.moveTo(0, 0);
    finShape.lineTo(0.8, -1.0); // Sharp sweep back
    finShape.lineTo(0.8, -1.8); // Vertical drop
    finShape.lineTo(0, -1.2); // Return to body

    const finGeo = new THREE.ExtrudeGeometry(finShape, {
      depth: 0.05,
      bevelEnabled: false,
    });

    for (let i = 0; i < 4; i++) {
      const finGroup = new THREE.Group();
      const fin = new THREE.Mesh(finGeo, matAccent);
      fin.position.y = -0.2;
      // Center breadth
      fin.position.z = -0.025;

      finGroup.add(fin);
      finGroup.rotation.y = (Math.PI / 2) * i;
      finGroup.translateZ(0.5); // Push out
      rocketGroup.add(finGroup);
    }

    // 6. Engine Block
    const engineBlockGeo = new THREE.CylinderGeometry(0.6, 0.5, 0.5, 8);
    const engineBlock = new THREE.Mesh(engineBlockGeo, matBodyDark);
    engineBlock.position.y = -1.5;
    rocketGroup.add(engineBlock);

    // Nozzle
    const nozzleGeo = new THREE.ConeGeometry(0.4, 0.5, 16, 1, true);
    const nozzle = new THREE.Mesh(nozzleGeo, matEngine);
    nozzle.position.y = -1.9;
    nozzle.rotation.x = Math.PI; // Point down
    rocketGroup.add(nozzle);

    // Hitbox for interaction
    const hitbox = new THREE.Mesh(
      new THREE.CylinderGeometry(1.5, 1.5, 5, 8),
      new THREE.MeshBasicMaterial({ visible: false })
    );
    rocketGroup.add(hitbox);

    // Initial Position
    const HOME_POS = new THREE.Vector3(5, 0, 0);
    rocketGroup.position.copy(HOME_POS);
    rocketGroup.rotation.set(0, 0, Math.PI / 6);

    // --- Particle System (Exhaust) ---
    const particles: {
      mesh: THREE.Mesh;
      life: number;
      velocity: THREE.Vector3;
      maxLife: number;
    }[] = [];
    const particleGeo = new THREE.SphereGeometry(1, 8, 8);
    const particleMat = new THREE.MeshBasicMaterial({
      color: 0xffaa00,
      transparent: true,
      opacity: 0.8,
    });

    const spawnParticle = (
      pos: THREE.Vector3,
      direction: THREE.Vector3,
      speed: number
    ) => {
      const mesh = new THREE.Mesh(particleGeo, particleMat.clone());
      mesh.position.copy(pos);
      mesh.position.add(
        new THREE.Vector3(
          (Math.random() - 0.5) * 0.2,
          (Math.random() - 0.5) * 0.2,
          (Math.random() - 0.5) * 0.2
        )
      );

      mesh.scale.setScalar(0.1 + Math.random() * 0.1);
      scene.add(mesh);

      const maxLife = 0.5 + Math.random() * 0.5;
      const spread = 0.08; // More spread for "cute" clouds
      const velocity = direction.clone().multiplyScalar(speed);
      velocity.x += (Math.random() - 0.5) * spread;
      velocity.y += (Math.random() - 0.5) * spread;
      velocity.z += (Math.random() - 0.5) * spread;

      particles.push({ mesh, life: maxLife, maxLife, velocity });
    };

    // --- Animation Logic ---
    const pathPoints = [
      HOME_POS.clone(),
      new THREE.Vector3(1, 4, 2),
      new THREE.Vector3(-4, 3, 5),
      new THREE.Vector3(-8, 0, 0),
      new THREE.Vector3(-4, -4, -4),
      new THREE.Vector3(4, -3, -6),
      new THREE.Vector3(7, -1, -2),
      HOME_POS.clone(),
    ];
    const flightPath = new THREE.CatmullRomCurve3(pathPoints);
    flightPath.closed = false;
    flightPath.tension = 0.5;

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2(-999, -999);
    let isHovered = false;
    let isFlying = false;
    let progress = 0;
    const flightSpeed = 0.003;
    let time = 0;

    const onMouseMove = (event: MouseEvent) => {
      const rect = renderer.domElement.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    };

    mountRef.current.addEventListener("mousemove", onMouseMove);

    const animate = () => {
      requestAnimationFrame(animate);
      time += 0.02;

      raycaster.setFromCamera(mouse, camera);
      const intersects = raycaster.intersectObject(hitbox);
      const isHit = intersects.length > 0;

      if (isHit && !isHovered) {
        isHovered = true;
        document.body.style.cursor = "pointer";
      } else if (!isHit && isHovered) {
        isHovered = false;
        document.body.style.cursor = "default";
      }

      if (isHovered && !isFlying) {
        isFlying = true;
        progress = 0;
      }

      const thrustDir = new THREE.Vector3(0, -1, 0);
      thrustDir.applyQuaternion(rocketGroup.quaternion);

      if (isFlying) {
        progress += flightSpeed;
        if (progress > 1) {
          progress = 1;
          isFlying = false;
          rocketGroup.position.copy(HOME_POS);
          rocketGroup.rotation.set(0, 0, Math.PI / 6);
        } else {
          const currentPos = flightPath.getPointAt(progress);
          const nextPos = flightPath.getPointAt(Math.min(progress + 0.01, 1));

          rocketGroup.position.copy(currentPos);
          rocketGroup.lookAt(nextPos);
          rocketGroup.rotateX(Math.PI / 2);

          // Banking
          const turnFactor = (currentPos.x - nextPos.x) * 0.8;
          rocketGroup.rotateZ(turnFactor);

          const enginePos = new THREE.Vector3(0, -2.0, 0);
          enginePos.applyMatrix4(rocketGroup.matrixWorld);

          const flightThrust = new THREE.Vector3(0, -1, 0).applyQuaternion(
            rocketGroup.quaternion
          );

          // Pink/White clouds for this cute rocket
          for (let k = 0; k < 4; k++)
            spawnParticle(enginePos, flightThrust, 0.4);
        }
      } else {
        // Idle
        rocketGroup.position.y = HOME_POS.y + Math.sin(time * 2) * 0.2;
        rocketGroup.rotation.z = Math.PI / 6 + Math.sin(time * 1.5) * 0.05;
        // Turn gently
        rocketGroup.rotation.y += 0.005;

        if (Math.random() > 0.8) {
          const enginePos = new THREE.Vector3(0, -2.0, 0);
          enginePos.applyMatrix4(rocketGroup.matrixWorld);
          const idleThrust = new THREE.Vector3(0, -1, 0).applyQuaternion(
            rocketGroup.quaternion
          );
          spawnParticle(enginePos, idleThrust, 0.1);
        }
      }

      // Particles
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.life -= 0.02;
        if (p.life <= 0) {
          scene.remove(p.mesh);
          particles.splice(i, 1);
        } else {
          p.mesh.position.add(p.velocity);
          p.mesh.scale.setScalar((p.maxLife - p.life) * 2.0);

          const m = p.mesh.material as THREE.MeshBasicMaterial;
          m.opacity = (p.life / p.maxLife) * 0.5;

          // Project Theme Colors: Cyan/Indigo/White
          const lifeRatio = p.life / p.maxLife;
          if (lifeRatio > 0.7) m.color.setHex(0x0ea5e9); // Sky Blue center
          else if (lifeRatio > 0.4) m.color.setHex(0x6366f1); // Indigo
          else m.color.setHex(0xffffff); // White smoke
        }
      }

      renderer.render(scene, camera);
    };

    animate();

    const handleResize = () => {
      if (!mountRef.current) return;
      const w = mountRef.current.clientWidth;
      const h = mountRef.current.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
      if (mountRef.current) {
        mountRef.current.removeEventListener("mousemove", onMouseMove);
        mountRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, []);

  return <div ref={mountRef} className="w-full h-full pointer-events-auto" />;
};
